#include <stdio.h>

int main(void) {
    int n;
    int a[32];
    if (scanf("%d", &n) != 1 || n < 1 || n > 32) return 1;
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) return 1;
    }

    int largest = a[0];
    for (int i = 1; i <= n; i++) {
        if (a[i] > largest) largest = a[i];
    }

    printf("%d\n", largest);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, count = 0;
    if (scanf("%d", &n) != 1) return 1;

    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) return 1;
        if (x > 0) count++;
    }

    printf("%d\n", count);
    return 0;
}

