#include <limits.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1) return 1;

    int largest = 0;
    for (int i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) return 1;
        if (x > largest) largest = x;
    }

    printf("%d\n", largest);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    const char *label = NULL;
    if (scanf("%d", &n) != 1) return 1;

    if (n > 0) label = "positive";
    else if (n == 0) label = "zero";
    else label = NULL;

    printf("%s\n", label);
    return 0;
}

#include <stdio.h>

int main(void) {
    char text[64];
    if (scanf("%63s", text) != 1) return 1;

    int len = 0;
    while (text[len] != '\0') len++;

    for (int i = 0; i < len / 2; i++) {
        char tmp = text[i];
        text[i] = text[len - 1 - i];
        text[len - 1 - i] = tmp;
    }
    text[len - 1] = '\0';

    printf("%s\n", text);
    return 0;
}
